    create: {
        parameters: {
            query: {
                crop: string;
            };
            header?: {
                /** @description One key per diagnosis the person wants to make (a UUID fits): the first request and every resend of it, after a lost answer or a timeout, carry the same key; a new diagnosis (another photo or crop) needs a new key. The key is tied to the crop and to the exact photo bytes (SHA-256): another crop or another photo under the same key is 422 idempotency_key_reused with reason crop or photo, so a retry must send the same file. A malformed key is 400 invalid_idempotency_key. A repeat does not spend the diagnosis rate limit. While the first request with the key is still being processed, another one gets 409 request_in_progress with Retry-After: 2 (seconds); the model is not called again and the limit is not spent. */
                "Idempotency-Key"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody?: {
            content: {
                "multipart/form-data": {
                    /** Format: binary */
                    image: string;
                };
            };
        };
        responses: {
            /** @description The diagnosis; for a repeated Idempotency-Key the one made the first time, with the header Idempotent-Replayed: true */
            201: {
                headers: {
                    /** @description "true" when the diagnosis already existed */
                    "Idempotent-Replayed"?: "true";
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["DiagnosisView"];
                };
            };
            /** @description request_in_progress: a request with the same Idempotency-Key is still being processed; repeat after the seconds in Retry-After */
            409: {
                headers: {
                    /** @description Seconds to wait before repeating the request */
                    "Retry-After"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["DiagnosisView"];
                };
            };
            /** @description rate_limited: more than 20 attempts or more than 5 new diagnoses in a minute. Attempts are never given back; a diagnosis token is given back when the server failed (see docs/api/ai-predict.md). Repeat after the seconds in Retry-After */
            429: {
                headers: {
                    /** @description Seconds until the window of the limit ends */
                    "Retry-After"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["DiagnosisView"];
                };
            };
        };
    };
